def analyze_soteriology_keywords(text):
    keywords = ["salvation", "grace", "faith", "redemption", "atonement"]
    keyword_counts = {keyword: 0 for keyword in keywords}

    # Convert the text to lowercase for case-insensitive matching
    text = text.lower()

