```JAVASCRIPT
CONST STRONGESTEXTENSION = (CLASS_NAME, EXTENSIONS) => {

  IF(TYPEOF CLASS_NAME !== 'STRING' || !ARRAY.ISARRAY(EXTENSIONS)) {
    THROW NEW ERROR("INVALID INPUT. EXPECT A STRING AND AN ARRAY OF STRINGS");
  }

  LET MAX_STRENGTH = -INFINITY, STRONGEST_EXT = '';
  FOR (LET EXT OF EXTENSIONS) {
    IF (TYPEOF EXT !== 'STRING') {
      THROW NEW ERROR("INVALID EXTENSION. ALL EXTENSIONS SHOULD BE STRINGS");
    }
    LET CAP = ARRAY.FROM(EXT).FILTER(X => X === X.TOUPPERCASE()).LENGTH;
    LET SM = ARRAY.FROM(EXT).FILTER(X => X === X.TOLOWERCASE()).LENGTH;
    LET STRENGTH = CAP - SM;
    IF (STRENGTH >= MAX_STRENGTH) {
      MAX_STRENGTH = STRENGTH;
      STRONGEST_EXT = EXT;
    }
  }

  RETURN `${CLASS_NAME}.${STRONGEST_EXT}`;
};
```

