def fibonacci(n, memo={}):
    if n in memo:
        return memo[n]
    if n == 0:
        return 0
    elif n == 1:
        return 1
    elif n < 0:
        result = (-1) ** (n + 1) * fibonacci(-n, memo)
    else:
        result = fibonacci(n - 1, memo) + fibonacci(n - 2, memo)
    memo[n] = result
    return result

def main():
    n = int(input())
    print(fibonacci(n))

if __name__ == "__main__":
    main()

