def analyze_appointment_data(appointments):
    from collections import defaultdict
    import datetime

    result = defaultdict(lambda: defaultdict(int))

    for appointment in appointments:
        try:
            appointment_date = datetime.datetime.strptime(appointment["appointment_date"], "%Y-%m-%d").date()
            month_year = appointment_date.strftime("%Y-%m")
            appointment_type = appointment["appointment_type"]
            result[month_year][appointment_type] += 1
