std::unordered_set<std::string> create_cyclic_permutations(const std::string& s)
{
    std::unordered_set<std::string> cyclic_permutations;
    for (size_t i = 0; i < s.size(); ++i)
    {
        std::string rotated = s.substr(i) + s.substr(0, i);
        cyclic_permutations.insert(rotated);
    }
    return cyclic_permutations;
}

std::string strip_and_lower(std::string s)
{
    s.erase(std::remove_if(s.begin(), s.end(), ::ispunct), s.end());
    std::transform(s.begin(), s.end(), s.begin(), ::tolower);

    return s;
}

bool cycled_pattern_search(const std::string& s1, const std::string& s2)
{
    std::string a = strip_and_lower(s1);
    std::string b = strip_and_lower(s2);

    auto cyclic_permutations = create_cyclic_permutations(b);

    return std::any_of(cyclic_permutations.begin(), cyclic_permutations.end(), [&a](const std::string& s) 
	{
	    return a.find(s) != std::string::npos;
	});
}
