def max_sum_non_adjacent(nums):
    if not nums:
        return 0
    elif len(nums) == 1:
        return max(0, nums[0])
    max_sum = [0]*len(nums)
    max_sum[0] = max(0, nums[0])
    max_sum[1] = max(max_sum[0], nums[1])
