```javascript
function createPDF() {

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName("Sheet1"); // specify the sheet name
  var data = sheet.getRange("D3:D" + sheet.getLastRow()).getValues(); 

  for(var i = 0; i < data.length; i++){
    if(data[i][0] != '') { // if column D is not empty
      var id = data[i][0];

      // Open the Google Doc that correspond to the ID on column D
      var doc = DocumentApp.openById(id);

      // Save a temp PDF version of the Doc  
