import sys
import random

class TreeNode:
    def __init__(self, key):
        self.key = key
        self.priority = random.randint(0, 1000000)  # Larger range to reduce collision
        self.left = None
        self.right = None

class Treap:
    def __init__(self):
        self.root = None

    def insert(self, key):
        self.root = self._insert(self.root, key)

    def _insert(self, root, key):
        if not root:
            return TreeNode(key)
        if key < root.key:
            root.left = self._insert(root.left, key)
            if root.left.priority > root.priority:
                root = self.rotateRight(root)
        elif key > root.key:
            root.right = self._insert(root.right, key)
            if root.right.priority > root.priority:
                root = self.rotateLeft(root)
        # Ignore duplicate keys
        return root

    def rotateRight(self, root):
        newRoot = root.left
        root.left = newRoot.right
        newRoot.right = root
        return newRoot

    def rotateLeft(self, root):
        newRoot = root.right
        root.right = newRoot.left
        newRoot.left = root
        return newRoot

    def inorder(self):
        result = []
        self._inorder(self.root, result)
        return result

    def _inorder(self, root, result):
        if root is not None:
            self._inorder(root.left, result)
            result.append(root.key)
            self._inorder(root.right, result)

    def preorder(self):
        result = []
        self._preorder(self.root, result)
        return result

    def _preorder(self, root, result):
        if root is not None:
            result.append(root.key)
            self._preorder(root.left, result)
            self._preorder(root.right, result)

    def postorder(self):
        result = []
        self._postorder(self.root, result)
        return result

    def _postorder(self, root, result):
        if root is not None:
            self._postorder(root.left, result)
            self._postorder(root.right, result)
            result.append(root.key)

def main():
    treap = Treap()
    n = int(sys.stdin.readline())
    for _ in range(n):
        line = sys.stdin.readline().strip()
        if not line:
            continue
        if line.startswith('insert'):
            _, x = line.split()
            treap.insert(int(x))
        elif line == 'inorder':
            print(' '.join(map(str, treap.inorder())))
        elif line == 'preorder':
            print(' '.join(map(str, treap.preorder())))
        elif line == 'postorder':
            print(' '.join(map(str, treap.postorder())))

if __name__ == '__main__':
    main()

