```JAVA
PUBLIC CLASS MAIN {

    PUBLIC STATIC VOID MAIN(STRING[] ARGS) {

        INT N1 = 0, N2 = 1, N3 = 0; //INITIALIZED VALUES OF THE FIRST 3 FIBONACCI SEQUENCE NUMBERS
        INT SUM = N1 + N2; //INITIAL SUM INITIALIZED TO THE SUM OF FIRST TWO NUMBERS

