import sys
import json
from collections import defaultdict

def main():
    sum_of_reciprocals = defaultdict(float)
    key_counts = defaultdict(int)
    lines = sys.stdin.read().strip().split('\n')
    for line in lines:
        if not line.strip():
            continue
        d = json.loads(line)
        for key, value in d.items():
            sum_of_reciprocals[key] += 1.0 / value
            key_counts[key] += 1
    harmonic_means = {key: key_counts[key] / sum_of_reciprocals[key] for key in sum_of_reciprocals}
    print(json.dumps(harmonic_means))

if __name__ == "__main__":
    main()

class BankAccount:
    def __init__(self):
        self.balance = 0
        self.transactions = 0

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            self.transactions += 1

    def withdraw(self, amount):
        if amount > 0:
            if self.balance >= amount:
                self.balance -= amount
                self.transactions += 1
                return True
            else:
                return False
        return False

    def get_balance(self):
        return self.balance

    def get_transaction_count(self):
        return self.transactions

