def main():
    s = input()
    words = []
    i = 0
    n = len(s)
    while i < n:
        # Skip over any spaces or punctuation (except [ and ])
        if s[i] == '[':
            # skip entire bracketed word
            i += 1
            start = i
            while i < n and s[i] != ']':
                i += 1
            # i is now at ']' or n
            i += 1 # move past ']'
            continue

        # Only consider alphanumeric chars and hyphens as in hyphenated words
        # Build a word (word can include internal hyphens for now)
        if s[i].isalpha():
            start = i
            while i < n and (s[i].isalpha() or s[i]=='-'):
                i += 1
            word = s[start:i]
            # Now break at hyphens
            parts = []
            part = ''
            for ch in word:
                if ch == '-':
                    if part != '':
                        parts.append(part)
                        part = ''
                else:
                    part += ch
            if part != '':
                parts.append(part)
            words.extend(parts)
        else:
            i += 1
    # Output
    # Remove any empty "words"
    filtered = [w for w in words if w]
    if not filtered:
        print()
        return
    # camelCase
    result = filtered[0].lower()
    for w in filtered[1:]:
        if w:
            result += w[0].upper() + w[1:].lower()
    print(result)

if __name__ == "__main__":
    main()

