<?php

require 'vendor/autoload.php';

use Aws\S3\S3Client;
use Aws\Exception\AwsException;

class S3ModifyMetadata {
    private $s3;
    private $bucket_names;
    private $metadata;

    function __construct($bucket_names, $metadata){
        $this->s3 = new S3Client([
            'region'  => 'us-west-2',
            'version' => '2006-03-01'
        ]);
        $this->bucket_names = $bucket_names;
        $this->metadata = $metadata;
    }

    function modify_metadata($bucket_name){
        try {
            $objects = $this->s3->listObjects([
                'Bucket' => $bucket_name
            ]);
            foreach ($objects['Contents'] as $object) {
                $result = $this->s3->headObject([
                    'Bucket' => $bucket_name,
                    'Key'    => $object['Key']
                ]);
                $metadata = $result['Metadata'];
                $metadata += $this->metadata;
                $this->s3->copyObject([
                    'Bucket'     => $bucket_name,
                    'Key'        => $object['Key'],
                    'CopySource' => "{$bucket_name}/{$object['Key']}",
                    'Metadata'   => $metadata,
                    'MetadataDirective' => 'REPLACE'
                ]);
            }
        }
        catch (S3Exception $e) {
            echo "There was an error uploading the file.\n";
        }
    }

    function modify_all_buckets(){
        foreach ($this->bucket_names as $bucket_name){
            $this->modify_metadata($bucket_name);
        }
    }
}

if (__NAMESPACE__ == "__main__"){
