    DAILY_LIMIT = 10000

    def __init__(self):
        self.balance = 0
        self.transaction_count = 0
        self.daily_transactions_total = 0

    def deposit(self, amount):
        if amount <= 0:
            print("Deposit amount must be positive.")
            return
        if self.daily_transactions_total + amount > self.DAILY_LIMIT:
            print(f"Deposit not allowed. Daily transaction limit of ${self.DAILY_LIMIT} exceeded.")
            return
        self.balance += amount
        self.transaction_count += 1
        self.daily_transactions_total += amount
        print(f"Deposited ${amount}. New balance is ${self.balance}.")

    def withdraw(self, amount):
        if amount <= 0:
            print("Withdrawal amount must be positive.")
            return
        if amount > self.balance:
            print("Insufficient funds.")
            return
        if self.daily_transactions_total + amount > self.DAILY_LIMIT:
            print(f"Withdrawal not allowed. Daily transaction limit of ${self.DAILY_LIMIT} exceeded.")
            return
        self.balance -= amount
        self.transaction_count += 1
        self.daily_transactions_total += amount
        print(f"Withdrew ${amount}. New balance is ${self.balance}.")

    def check_balance(self):
        print(f"Current balance is ${self.balance}.")

    def get_transaction_count(self):
        print(f"Total number of transactions: {self.transaction_count}.")

    def reset_daily_transactions(self):
