import unicodedata
import string

def is_valid_email(email):
    email = unicodedata.normalize('NFKC', email)
    if email.count('@') != 1:
        return False
    local, domain = email.split('@')
    if not local or not domain:
        return False
    local_allowed_chars = set(string.ascii_letters + string.digits + "!#$%&'*+/=?^_`{|}~-")
    domain_allowed_chars = set(string.ascii_letters + string.digits + '-')
    for char in local:
        if ord(char) > 127:
            continue
        if char not in local_allowed_chars:
            return False
    labels = domain.split('.')
    if len(labels) < 2:
        return False
    for label in labels:
        if not label:
            return False
        if label.startswith('-') or label.endswith('-') or label[0].isdigit():
            return False
        for char in label:
            if ord(char) > 127:
                continue
            if char not in domain_allowed_chars:
                return False
    return True

def main():
