def get_distribution_schema(key: str) -> dict:
    """
    Return the predefined distribution schema corresponding to `key`.

    Parameters
    ----------
    key : str
        Identifier of the desired distribution schema.

    Returns
    -------
    dict
        A dictionary describing the distribution parameters if `key` exists;
        otherwise, an empty dictionary.
    """
    schemas = {
        'A': {'type': 'uniform',  'range': '0-100'},
        'B': {'type': 'normal',   'mean': '50', 'stddev': '15'},
        'C': {'type': 'binomial', 'n': '10',    'p': '0.5'}
