    stop_words = ["the", "and", "is", "in", "to", "of", "a", "that", "it", "for", "as", "on", "with", "by", "at", "from"]
    import sys
    text = sys.stdin.readline().strip()
    # Lowercase the text
    text = text.lower()
    # Replace punctuation (excluding apostrophe) with space
    punctuation = '.,!?;:\"()[]{}'
    for char in punctuation:
        text = text.replace(char, ' ')
    # Split into words, keep contractions as single words
    words = []
    i = 0
    while i < len(text):
        # Accept word characters or apostrophe (for contractions)
        if text[i].isalpha() or text[i] == "'":
            start = i
            while i < len(text) and (text[i].isalpha() or text[i] == "'"):
                i += 1
            word = text[start:i]
            words.append(word)
        else:
            i += 1
    # Count word frequencies, ignoring stop words
    frequency = {}
    word_order = []
    for word in words:
        if word == '' or word in stop_words:
            continue
        if word not in frequency:
            frequency[word] = 1
            word_order.append(word)
        else:
            frequency[word] += 1
    # Sort by frequency descending, tie by first appearance
    result = []
    used = set()
    for _ in range(len(word_order)):
        maxfreq = -1
        maxword = None
        for word in word_order:
            if word not in used and frequency[word] > maxfreq:
                maxfreq = frequency[word]
                maxword = word
        if maxword is not None:
            result.append((maxword, frequency[maxword]))
            used.add(maxword)
    for word, freq in result:
        print(f"{word} {freq}")

