import re
import math

def validate_math_formula(formula):
    stack = []
    last_char = ""
    brackets = {'(': ')', '[': ']', '{': '}', '<': '>'}
    operators = ["+", "-", "*", "/"]
    functions = dir(math)

    balance = syntax = functions_usage = constants_usage = True

    for char in formula:
        if (char in brackets.keys()):
            stack.append(char)
        elif (char in brackets.values()):
            if (not stack or brackets[stack.pop()] != char):
                balance = False
                break
        elif (char in operators):
            if last_char in operators or last_char == "" or last_char in brackets.keys():
                syntax = False
                break
        elif (char.isdigit() and last_char in operators and stack and stack[-1] in brackets.keys()):
            syntax = False
            break
        last_char = char

    if stack:
        balance = False

    formula_parts = re.split(r"[\+\-\*\/\(\)\[\]\{\}\<\>\s]+", formula)

    for part in formula_parts:
        if part in functions:
            if not re.match(r"^{0}\s*\(.+\)$".format(part), formula):
                functions_usage = False
                break
        elif re.match(r"^[\d\.]+$", part):
            if "pi" in part or "e" in part:
                constants_usage = False
                break
        elif part != "":
            syntax = False

    return balance, syntax, functions_usage, constants_usage

