class OrderedSet:
    def __init__(self):
        self.elements = {}
        self.order = []

    def add(self, value):
        if value not in self.elements:
            self.elements[value] = True
            inserted = False
            for i, v in enumerate(self.order):
                if value < v:
                    self.order.insert(i, value)
                    inserted = True
                    break
            if not inserted:
                self.order.append(value)

    def get_second_smallest(self):
        if len(self.order) < 2:
            return None
        return self.order[1]

