class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def collinear(self, *points):
        all_points = [self] + list(points)
        if len(all_points) < 3:
            return False
        p0 = all_points[0]
        all_same = True
        for p in all_points[1:]:
            if p.x != p0.x or p.y != p0.y:
                all_same = False
                break
        if all_same:
            return True
        # Find the first point different from p0
        p1 = None
        for p in all_points:
            if p.x != p0.x or p.y != p0.y:
                p1 = p
                break
        dx = p1.x - p0.x
        dy = p1.y - p0.y
        for p in all_points:
            if dx * (p.y - p0.y) != dy * (p.x - p0.x):
                return False
        return True

