FUNCTION VERSATILEMEDIAN(L, CMP_FUNC) {
    IF (TYPEOF CMP_FUNC !== "FUNCTION"){
        THROW NEW TYPEERROR("CMP_FUNC SHOULD BE A CALLABLE FUNCTION");
    }
    IF (!L.EVERY(I => TYPEOF I === "NUMBER" || ARRAY.ISARRAY(I))){
        THROW NEW TYPEERROR("LIST SHOULD CONTAIN ONLY NUMBERS OR ARRAYS");
    }

    CONST TOTAL_ELEMENTS = L.REDUCE((ACC, EL) => {
        IF (ARRAY.ISARRAY(EL)) RETURN ACC + EL.LENGTH;
        ELSE RETURN ACC + 1;
    }, 0);

    LET MEDIAN;

    IF (TOTAL_ELEMENTS % 2 === 0){
        CONST FIRST_MID = MATH.FLOOR(TOTAL_ELEMENTS / 2);
        CONST SECOND_MID = MATH.FLOOR(TOTAL_ELEMENTS / 2) + 1;
        CONST FIRST_MID_VALUE = GETELEMENTBYPOSITION(L, CMP_FUNC, FIRST_MID);
        CONST SECOND_MID_VALUE = GETELEMENTBYPOSITION(L, CMP_FUNC, SECOND_MID);
        MEDIAN = (FIRST_MID_VALUE + SECOND_MID_VALUE) / 2.0;
    } ELSE {
        CONST MID = MATH.FLOOR(TOTAL_ELEMENTS / 2) + 1;
        MEDIAN = GETELEMENTBYPOSITION(L, CMP_FUNC, MID);
    }

    RETURN MEDIAN;
}

FUNCTION GETELEMENTBYPOSITION(L, CMP_FUNC, POS){
    LET COUNT = 0;
    FOR (LET I OF L){
        IF (ARRAY.ISARRAY(I)){
            FOR (LET J OF I){
                CHECK_NUMBER(J);
                COUNT += 1;
                IF (COUNT === POS){
                    RETURN J;
                }
            }
        } ELSE {
            CHECK_NUMBER(I);
            COUNT += 1;
            IF (COUNT === POS){
                RETURN I;
            }
        }
    }
    THROW NEW ERROR("POSITION OUT OF RANGE");
}

