import sys, math

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def build_tree(values):
    """Constructs binary tree from a list of strings given in level order."""
    if not values or values[0] == 'N':
        return None

    root = Node(int(values[0]))
    queue = [root]
    idx = 1
    n = len(values)

    while queue and idx < n:
        current = queue.pop(0)

        # left child
        if idx < n and values[idx] != 'N':
            current.left = Node(int(values[idx]))
            queue.append(current.left)
        idx += 1

        # right child
        if idx < n and values[idx] != 'N':
            current.right = Node(int(values[idx]))
            queue.append(current.right)
        idx += 1

    return root

def maxGCD(root):
    if not root:
        return 0

    max_gcd = -1
    result_node_val = 0
    stack = [root]

    while stack:
        node = stack.pop()

        if node.left and node.right:
            current_gcd = math.gcd(node.left.val, node.right.val)
            if current_gcd > max_gcd:
                max_gcd = current_gcd
                result_node_val = node.val
            elif current_gcd == max_gcd and node.val > result_node_val:
                result_node_val = node.val

        if node.right:
            stack.append(node.right)
        if node.left:
            stack.append(node.left)

    return result_node_val if max_gcd != -1 else 0

