def sieve_primes_1_mod_4(limit):
    # Returns all primes <= limit and == 1 mod 4
    if limit < 2:
        return []
    is_prime_arr = [True] * (limit + 1)
    is_prime_arr[0] = is_prime_arr[1] = False
    for p in range(2, int(limit ** 0.5) + 1):
        if is_prime_arr[p]:
            for i in range(p * p, limit + 1, p):
                is_prime_arr[i] = False
    return [i for i, prime in enumerate(is_prime_arr) if prime and i % 4 == 1]

