def recursive_sum(numbers, index=0, total=0):
    if index == len(numbers):
        return total
    return recursive_sum(numbers, index + 1, total + numbers[index])

def moving_average_recursive(numbers, window_size, start_index=0, averages=None):
    if averages is None:
        averages = []
    if window_size > len(numbers) or window_size <= 0 or start_index + window_size > len(numbers):
        return averages
    current_window = numbers[start_index:start_index + window_size]
    window_sum = recursive_sum(current_window)
    averages.append(window_sum / window_size)
    return moving_average_recursive(numbers, window_size, start_index + 1, averages)

